package com.agriconnect.model; import jakarta.persistence.*; import java.math.BigDecimal; @Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name,category,unit,description,location; private BigDecimal price; private int quantity; @ManyToOne private AppUser farmer; public Long getId(){return id;} public void setId(Long v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getUnit(){return unit;} public void setUnit(String v){unit=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public AppUser getFarmer(){return farmer;} public void setFarmer(AppUser v){farmer=v;} }